export const PRICE_BANDS={surplus:{name:'Abundant capacity',factor:.8},standard:{name:'Normal capacity',factor:1},tight:{name:'Tight capacity',factor:1.25}};
export function contractRate(kind,direction,band='standard'){const base=kind==='power'?(direction==='import'?.5:.4):kind==='water'?(direction==='import'?.3:.2):2;return Math.round(base*PRICE_BANDS[band].factor*100)/100;}
export function contractQuote(c,connection,kind,direction,amount){const n=c.region.neighbors[connection.side],used=kind==='garbage'?n.wasteStored:n.population*(kind==='power'?.04:.035),capacity=n[kind==='garbage'?'wasteCapacity':kind+'Capacity'],utilization=capacity?used/capacity:1,priceBand=utilization<.1?'surplus':utilization>=.8?'tight':'standard',rate=contractRate(kind,direction,priceBand),minFee=kind==='garbage'?15:10;return{priceBand,rate,minFee,utilization,earlyFee:Math.ceil(Math.max(minFee,amount*rate)*12)};}
